#include "rooms.hpp"

/*
 * ROM 0x0864F830-0x087E3BEC: the 41 rooms' level assets (gRoomNNAsset), the
 * per-layer chunk streams that DecodeLayerChunk/DecodeCollisionChunk read
 * (docs/levels.md). 34 are LZ77-packed (gbagfx) and 7 are raw; the room's
 * `struct level_desc` says which. Each starts on a word boundary, hence
 * aligned(4): the 0-3 zero bytes after a packed one are the next one's
 * alignment.
 *
 * The definitions are generated by tools/levels.py from data/levels/
 * (levels.json's "assets" list gives their ROM order, each room.json the
 * symbol and whether it's packed), the bytes by tools/bin2c.py from the
 * assets levels.mk builds. Linked in ROM order between data/data.s
 * sections by games/xs/ldscript.txt, see docs/data.md.
 */
#include "level_assets.inc"
